const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',cases:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',queue:'<path d="M4 6h16M4 12h16M4 18h11"/><circle cx="19" cy="18" r="2"/>',challenge:'<path d="M12 2 4 5v6c0 5 3.4 8.4 8 11 4.6-2.6 8-6 8-11V5l-8-3Z"/><path d="m9 12 2 2 4-4"/>',related:'<circle cx="5" cy="12" r="2"/><circle cx="19" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="m7 11 10-5M7 13l10 5"/>',policy:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',risk:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',actions:'<path d="m3 12 6 6L21 6"/>',controls:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2" fill="white"/><circle cx="15" cy="17" r="2" fill="white"/>',reports:'<path d="M4 20V10M10 20V4M16 20v-7M22 20V8"/>',audit:'<path d="M12 8v5l3 2"/><circle cx="12" cy="12" r="9"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',file:'<path d="M6 2h8l4 4v16H6z"/><path d="M14 2v5h4M9 12h6M9 16h6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',alert:'<path d="m12 3 9 16H3L12 3Z"/><path d="M12 9v4M12 17h.01"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 18v3h16v-3"/>'};
const icon=n=>`<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24">${icons[n]||icons.file}</svg></span>`;
const docs={PR:{title:'Purchase Request',ref:'PR-2291',date:'May 1, 2026',owner:'Michael Tan',facts:['Requester: Michael Tan','Department: IT Infrastructure','Requested: 10 units','Budget: USD 120,000']},QUOTE:{title:'Supplier Quotation',ref:'QT-4408',date:'May 3, 2026',owner:'ABC Technology',facts:['Quoted: 10 units','Value: USD 120,000','Category: End-user computing']},PO:{title:'Purchase Order',ref:'PO-8821',date:'May 5, 2026',owner:'Procurement Office',facts:['Vendor: ABC Technology','Ordered: 10 units','Approved PO amount: USD 120,000']},GR:{title:'Goods Receipt',ref:'GR-6620',date:'May 7, 2026',owner:'IT Infrastructure',facts:['Received: 8 of 10 units','Outstanding: 2 units','Receipt status: Partial']},INV:{title:'Invoice',ref:'INV-0092',date:'May 8, 2026',owner:'ABC Technology',facts:['Invoice amount: USD 135,000','Billed quantity: 10 units','PO reference: PO-8821']},APR:{title:'Approval Record',ref:'APR-1138',date:'May 5, 2026',owner:'Procurement Office',facts:['Approver role found: Manager','Director approval: Not found','Approved against PO-8821']},POL:{title:'Procurement Policy',ref:'Policy §4.2 / §4.5',date:'Effective Jan 1, 2026',owner:'Policy Office',facts:['§4.2: Purchases above USD 100,000 require Director approval','§4.5: Related purchases within 7 days require cumulative review']},REL:{title:'Related Purchase Order',ref:'PO-8794',date:'May 2, 2026',owner:'IT Infrastructure',facts:['Vendor: ABC Technology','Requester: Michael Tan','Category: End-user computing','PO amount: USD 78,000']}};
const cases=[{id:'PC-2026-0187',vendor:'ABC Technology',requester:'Michael Tan',dept:'IT Infrastructure',amount:'USD 135,000',risk:89,status:'Pending Review',rec:'Hold Payment'}, {id:'PC-2026-0184',vendor:'Northstar Office',requester:'Rachel Chen',dept:'Operations',amount:'USD 24,500',risk:41,status:'In Review',rec:'Request Clarification'}, {id:'PC-2026-0179',vendor:'Vertex Logistics',requester:'Oliver Lee',dept:'Facilities',amount:'USD 62,800',risk:18,status:'Reviewed',rec:'Proceed'}];
const stages=['Reconstructing procurement story','Comparing values across documents','Checking policy rules','Searching related transactions','Assessing approval integrity','Generating recommendation'];
const findings=[{title:'Price variance',severity:'High',copy:'The invoice exceeds the approved PO by USD 15,000 (12.5%). No approved change order appears in the case evidence.',evidence:'PO-8821: USD 120,000  ·  INV-0092: USD 135,000',refs:['PO','INV']},{title:'Delivery mismatch',severity:'High',copy:'The invoice bills 10 units, while the goods receipt confirms only 8 units received. Two units remain unverified.',evidence:'PO-8821: 10 ordered  ·  GR-6620: 8 received  ·  INV-0092: 10 billed',refs:['PO','GR','INV']},{title:'Approval gap',severity:'Critical',copy:'The PO exceeds the USD 100,000 threshold, but the only recorded approval is from a Manager.',evidence:'APR-1138: Manager  ·  Policy §4.2: Director required',refs:['APR','POL']},{title:'Potential split purchase',severity:'Critical',copy:'A USD 78,000 purchase was issued three days earlier with the same vendor, requester and category. The pattern warrants cumulative review; intent is not established.',evidence:'PO-8794: USD 78,000  ·  PO-8821: USD 120,000  ·  Policy §4.5',refs:['REL','PO','POL']}];
const baseAudit=[{time:'May 8, 2026 · 10:24',who:'System',what:'Case assembled',detail:'Linked PR-2291, QT-4408, PO-8821, GR-6620, INV-0092 and APR-1138.'},{time:'May 8, 2026 · 10:28',who:'System',what:'Related transaction indexed',detail:'PO-8794 linked by vendor, requester, category and 3-day proximity.'},{time:'May 8, 2026 · 10:31',who:'System',what:'Payment request queued',detail:'Case PC-2026-0187 placed in review queue. No payment action recorded.'}];
const fresh=()=>({view:'login',challenged:false,challenging:false,stage:-1,paymentHeld:false,clarificationRequested:false,escalated:false,approvalRequested:false,controlDraft:false,controlActive:false,draftType:null,search:'',riskFilter:'All risks',audit:[],signedIn:false});
let state=fresh(),timer=null,toastTimer=null;
const nav=[['dashboard','Dashboard'],['cases','Cases'],['queue','Review Queue'],['case','Case Review'],['challenge','Challenge This Purchase'],['related','Related Transactions'],['policy','Policy Check'],['risk','Risk & Recommendation'],['simulator','Review & Repair Lab'],['secondlook','Second-Look Review'],['actions','Action Center'],['controls','Controls'],['reports','Reports'],['audit','Audit Trail'],['settings','Settings']];
const navGroup=k=>['dashboard','cases','queue','case','challenge','related','policy','risk','simulator','secondlook','actions'].includes(k)?'WORKSPACE':'GOVERNANCE';
function status(){return state.paymentHeld?'Payment Held':state.escalated?'Escalated':state.clarificationRequested?'Clarification Requested':'Pending Review'}
function addAudit(what,detail,who='Demo reviewer'){state.audit.unshift({time:new Date().toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit'}),who,what,detail})}
function showToast(msg){const root=document.getElementById('toast-root');root.innerHTML=`<div class="toast">${msg}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>root.innerHTML='',3400)}
function go(view){state.view=view;render();window.scrollTo({top:0,behavior:'smooth'})}
function login(){state.signedIn=true;addAudit('Demo session started','Reviewer opened the illustrative procurement workspace.');go('dashboard')}
function shell(){const item=(v,l)=>`<button class="nav-btn ${state.view===v?'active':''}" data-nav="${v}" aria-current="${state.view===v?'page':'false'}">${icon(v)}<span>${l}</span></button>`;return `<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">P</span>ProcureMind</div><nav aria-label="Main navigation"><div class="nav-label">Workspace</div>${nav.filter(x=>navGroup(x[0])==='WORKSPACE').map(x=>item(...x)).join('')}<div class="nav-label">Governance</div>${nav.filter(x=>navGroup(x[0])==='GOVERNANCE').map(x=>item(...x)).join('')}</nav><div class="sidebar-bottom"><div class="demo-tag"><b>ILLUSTRATIVE DEMO</b><br>Sample records and simulated actions for product review.</div></div></aside><div class="main"><header class="topbar"><div class="search">${icon('search')}<input id="global-search" aria-label="Search cases, vendors and documents" placeholder="Search cases, vendors, POs, invoices" value="${state.search.replaceAll('"','&quot;')}"></div><div class="row"><button class="btn btn-primary btn-small" data-nav="case">${icon('challenge')} New Review</button><span class="avatar">SC</span><div class="top-user"><b>Sarah Chen</b><span class="muted">Finance Controller</span></div></div></header><main class="content">${view()}</main></div></div>`}
function loginView(){return `<div class="login"><div class="login-left"><div class="brand"><span class="brand-mark">P</span>ProcureMind</div><div class="login-form"><div class="eyebrow">PROCUREMENT DECISION INTELLIGENCE</div><h1>Welcome to<br>ProcureMind</h1><p>Challenge procurement decisions before money moves.</p><form id="login-form"><div class="field"><label for="email">Work email</label><input id="email" type="email" placeholder="name@company.com" autocomplete="username"></div><div class="field"><label for="password">Password</label><input id="password" type="password" placeholder="Enter your password" autocomplete="current-password"></div><button type="submit" class="btn btn-primary">Enter demo workspace ${icon('arrow')}</button></form><button class="btn btn-outline" data-action="login">Continue with SSO demo</button><div class="small muted" style="margin-top:14px">Demo access is local to this prototype. No credentials are required or transmitted.</div></div><div class="login-foot">© 2026 ProcureMind · Illustrative hackathon prototype</div></div><div class="login-right"><div class="hero-graphic"><div class="eyebrow" style="color:#9dbbf4">BEFORE APPROVAL. BEFORE PAYMENT.</div><h2>See the story behind every purchase.</h2><p>Connect documents, transactions, approvals and policy into one defensible procurement decision.</p><div class="story-strip"><div class="story-chip">Documents</div><span class="story-arrow">→</span><div class="story-chip">Relationships</div><span class="story-arrow">→</span><div class="story-chip">Decision</div></div><div class="login-proof"><h3>What ProcureMind does</h3><ul><li><span class="tick">✓</span>Reconstructs the purchase story across evidence</li><li><span class="tick">✓</span>Finds hidden cross-transaction patterns</li><li><span class="tick">✓</span>Shows the policy behind each finding</li><li><span class="tick">✓</span>Recommends the next defensible action</li></ul></div></div></div></div>`}
function header(title,sub,actions='',crumb=''){return `<div class="crumb">${crumb||'ProcureMind / Workspace'}</div><div class="headline"><div><h1 class="page-title">${title}</h1><p class="page-sub">${sub}</p></div>${actions?`<div class="headline-actions">${actions}</div>`:''}</div>`}
function metric(label,value,foot,ico='dashboard',color=''){return `<div class="card metric"><div class="between"><div class="metric-label">${label}</div><div class="metric-icon ${color}">${icon(ico)}</div></div><div class="metric-value mono">${value}</div><div class="metric-foot">${foot}</div></div>`}
function sectionHead(title,sub,action=''){return `<div class="card-head between"><div><h2 class="section-title">${title}</h2>${sub?`<p class="section-sub">${sub}</p>`:''}</div>${action}</div>`}
function caseTable(rows){return `<div class="table-wrap"><table class="table"><thead><tr><th>Case ID</th><th>Vendor</th><th>Requester</th><th>Amount</th><th>Risk</th><th>Status</th><th>Recommendation</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td>${c.id==='PC-2026-0187'?`<button class="link" data-nav="case">${c.id}</button>`:c.id}</td><td><strong>${c.vendor}</strong></td><td>${c.requester}</td><td class="mono">${c.amount}</td><td><span class="pill ${c.risk>70?'red':c.risk>30?'amber':'green'}"><span class="dot"></span>${c.risk} / 100</span></td><td>${c.id==='PC-2026-0187'?status():c.status}</td><td>${c.rec}</td><td>${c.id==='PC-2026-0187'?`<button class="btn btn-outline btn-small" data-nav="case">Open Case</button>`:`<span class="small muted">Sample only</span>`}</td></tr>`).join('')}</tbody></table></div>`}
function dashboard(){return `${header('Dashboard','Procurement review intelligence across current cases',`<button class="btn btn-primary" data-nav="case">Open priority case ${icon('arrow')}</button>`)}<div class="stack"><div class="grid-3">${metric('Cases reviewed today','128','Illustrative portfolio view','cases')}${metric('High-risk cases','14','Requires human review','alert','red')}${metric('Payments held for review','USD 1.24M','Illustrative portfolio view','risk','amber')}${metric('Policy violations detected','27','Across sampled cases','policy','amber')}${metric('Potential split purchases','6','Signals requiring investigation','related','red')}${metric('Average review time','4.2 min','Illustrative portfolio view','audit','green')}</div><div class="product-banner"><div><div class="eyebrow" style="color:#9cc2ff">WHY PROCUREMIND IS DIFFERENT</div><h2>Challenge procurement decisions before money moves.</h2><p>Traditional systems check whether documents match. ProcureMind checks whether the entire story behind a purchase makes sense.</p></div><button class="btn" data-nav="challenge">See the challenge ${icon('arrow')}</button></div><div class="grid-2"><div class="compare-item"><b>Traditional document check</b><p>Invoice, PO, receipt and approval are reviewed as separate records.</p></div><div class="compare-item procure"><b>ProcureMind story review</b><p>Evidence is connected across the full case and related transactions, then tied to a decision.</p></div></div><div class="card">${sectionHead('Priority review','Start with the case most likely to change a payment decision')}<div class="card-body"><div class="feature-case"><div><span class="case-id">PC-2026-0187</span><h3>ABC Technology · IT Infrastructure</h3><p>Invoice variance, partial delivery, missing Director approval and a related purchase.</p><div class="case-mini"><div>INVOICE<b>USD 135,000</b></div><div>RISK SCORE<b style="color:var(--red)">89 / 100</b></div><div>RECOMMENDATION<b>HOLD PAYMENT</b></div></div></div><button class="btn btn-primary" data-nav="case">Review Case ${icon('arrow')}</button></div></div></div><div class="grid-2"><div class="card">${sectionHead('Risk distribution','Illustrative portfolio mix')}<div class="card-body risk-bars"><div class="risk-bar"><span>High risk</span><div class="bar-track"><div class="bar-fill red" style="width:28%"></div></div><b>14</b></div><div class="risk-bar"><span>Medium risk</span><div class="bar-track"><div class="bar-fill amber" style="width:48%"></div></div><b>24</b></div><div class="risk-bar"><span>Low risk</span><div class="bar-track"><div class="bar-fill green" style="width:84%"></div></div><b>42</b></div></div></div><div class="card">${sectionHead('Recent flags','Signals surfaced in the review queue')}<div class="card-body"><div class="signal">${icon('alert')}<div><strong>INV-0092 · Invoice exceeds PO</strong><span>USD 15,000 variance</span></div></div><div class="signal">${icon('related')}<div><strong>PO-8821 · Related purchase found</strong><span>Same vendor and requester, three days apart</span></div></div><div class="signal">${icon('policy')}<div><strong>APR-1138 · Director approval missing</strong><span>Procurement Policy §4.2</span></div></div></div></div></div><div class="card">${sectionHead('Review queue','Most recent sample cases',`<button class="btn btn-plain" data-nav="cases">View all cases ${icon('arrow')}</button>`)}${caseTable(cases)}</div></div>`}function queueView(){const queued=cases.filter(c=>c.status==='Pending Review'||c.status==='In Review').sort((a,b)=>b.risk-a.risk);return `${header('Review Queue','Prioritized cases awaiting a human decision',`<button class="btn btn-outline" data-nav="cases">Browse all cases ${icon('arrow')}</button>`)}<div class="stack"><div class="grid-3">${metric('Cases awaiting review',String(queued.length),'Illustrative sample queue','queue')}${metric('High-risk priority',String(queued.filter(c=>c.risk>70).length),'Review before payment','alert','red')}${metric('Next case','PC-2026-0187','Risk 89 / 100','case','amber')}</div><div class="card card-pad between wrap"><div><span class="eyebrow">NEXT REVIEW · HIGH RISK</span><h2 class="section-title" style="margin:8px 0">PC-2026-0187 · ABC Technology</h2><p class="section-sub">Invoice variance, partial delivery, Manager-only approval and a related purchase need a decision before payment.</p><div class="row wrap" style="margin-top:12px"><span class="pill red">Risk 89 / 100</span><span class="pill amber">${status()}</span></div></div><button class="btn btn-primary" data-nav="case">Review priority case ${icon('arrow')}</button></div><div class="card">${sectionHead('Cases awaiting review','Highest risk first · reviewed cases are listed under Cases')}${caseTable(queued)}</div></div>`}
function casesView(){const q=state.search.toLowerCase().trim();let rows=cases.filter(c=>(!q||Object.values(c).join(' ').toLowerCase().includes(q))&&(state.riskFilter==='All risks'||(state.riskFilter==='High risk'&&c.risk>70)||(state.riskFilter==='Medium risk'&&c.risk>30&&c.risk<=70)||(state.riskFilter==='Low risk'&&c.risk<=30)));return `${header('Procurement Cases','Search and prioritize reviews before approval or payment',`<button class="btn btn-primary" data-nav="case">New Review ${icon('arrow')}</button>`)}<div class="card"><div class="card-body"><div class="filter-row"><select class="filter" id="risk-filter" aria-label="Filter by risk"><option ${state.riskFilter==='All risks'?'selected':''}>All risks</option><option ${state.riskFilter==='High risk'?'selected':''}>High risk</option><option ${state.riskFilter==='Medium risk'?'selected':''}>Medium risk</option><option ${state.riskFilter==='Low risk'?'selected':''}>Low risk</option></select><span class="pill gray">${rows.length} cases</span><span class="small muted">Sample cases for prototype navigation</span></div></div>${rows.length?caseTable(rows):'<div class="empty">No cases match this search. Try a case ID, vendor or requester.</div>'}</div>`}
function documentCard(k){const d=docs[k];return `<div class="doc">${icon('file')}<div><b>${d.title}</b><p>${d.ref} · ${d.date}</p></div><button data-doc="${k}">View</button></div>`}
function caseView(){return `${header('Case Review: PC-2026-0187','ABC Technology · IT Infrastructure · Requested by Michael Tan',`<button class="btn btn-outline" data-action="clarification">Generate Clarification</button><button class="btn btn-primary" data-action="challenge">${icon('challenge')} Challenge This Purchase</button>`,`<button data-nav="cases">Cases</button> / PC-2026-0187`)}<div class="stack"><div class="card card-pad between wrap"><div class="row wrap"><span class="pill ${state.paymentHeld?'red':'amber'}"><span class="dot"></span>${status()}</span><span class="small muted">Payment request · INV-0092 · USD 135,000</span></div><div class="row"><span class="small muted">Case owner: Sarah Chen</span><span class="pill red">Risk 89 / 100</span></div></div><div class="summary-grid"><div class="summary-tile"><span>PO amount</span><b>USD 120,000</b></div><div class="summary-tile alert"><span>Invoice amount</span><b>USD 135,000</b></div><div class="summary-tile alert"><span>Goods received</span><b>8 / 10 units</b></div><div class="summary-tile alert"><span>Approval found</span><b>Manager only</b></div><div class="summary-tile"><span>Required approval</span><b>Director</b></div></div><div class="two-col"><div class="stack"><div class="card">${sectionHead('Procurement story','Source-backed events in time order',`<button class="btn btn-plain" data-nav="challenge">Run challenge ${icon('arrow')}</button>`)}<div class="card-body timeline"><div class="event"><div class="event-top"><b>Purchase requested</b><time>May 1, 2026</time></div><p>Michael Tan requests 10 units for IT Infrastructure · <button class="source-link" data-doc="PR">PR-2291</button></p></div><div class="event"><div class="event-top"><b>Related purchase issued</b><time>May 2, 2026</time></div><p>ABC Technology · USD 78,000 · <button class="source-link" data-doc="REL">PO-8794</button></p></div><div class="event"><div class="event-top"><b>Quotation and PO established</b><time>May 3–5, 2026</time></div><p>10 units · USD 120,000 · <button class="source-link" data-doc="QUOTE">QT-4408</button> / <button class="source-link" data-doc="PO">PO-8821</button></p></div><div class="event issue"><div class="event-top"><b>Partial delivery logged</b><time>May 7, 2026</time></div><p>8 of 10 units received · <button class="source-link" data-doc="GR">GR-6620</button></p></div><div class="event issue"><div class="event-top"><b>Invoice submitted and payment requested</b><time>May 8, 2026</time></div><p>USD 135,000 for 10 units · <button class="source-link" data-doc="INV">INV-0092</button></p></div></div></div><div class="card">${sectionHead('Documents in scope','Click any record to inspect the evidence') }<div class="card-body doc-grid">${['PR','QUOTE','PO','GR','INV','APR','REL','POL'].map(documentCard).join('')}</div></div></div><div class="stack"><div class="challenge-hero"><div class="eyebrow" style="color:#93c5fd">PRIMARY REVIEW</div><h2>Does this purchase story make sense?</h2><p>Challenge the case across documents, approval rules and neighboring transactions.</p><button class="btn" data-action="challenge">Challenge This Purchase ${icon('arrow')}</button></div><div class="card">${sectionHead('Decision preview','Review before releasing funds')}<div class="card-body"><div class="between"><div><div class="eyebrow">RECOMMENDATION</div><h2 style="font:800 19px Manrope;margin:8px 0;color:var(--red)">HOLD PAYMENT</h2></div><span class="pill red">High risk</span></div><p class="small muted" style="line-height:1.6">Evidence indicates a price variance, incomplete delivery and missing Director approval. A related purchase also needs cumulative review.</p><button class="btn btn-outline" data-nav="risk">View recommendation ${icon('arrow')}</button></div></div></div></div></div>`}
function steps(){return `<div class="step-list">${stages.map((s,i)=>`<div class="step ${state.challenged||i<state.stage?'done':i===state.stage?'active':''}"><span class="step-icon">${state.challenged||i<state.stage?'✓':String(i+1)}</span><span>${s}</span></div>`).join('')}</div>`}
function findingCard(f){return `<article class="issue"><div class="between"><h3>${f.title}</h3><span class="pill ${f.severity==='Critical'?'red':'amber'}">${f.severity}</span></div><p>${f.copy}</p><div class="evidence"><b>Evidence:</b> ${f.evidence}<div style="margin-top:6px">${f.refs.map(k=>`<button class="source-link" data-doc="${k}">${docs[k].ref}</button>`).join(' · ')}</div></div></article>`}
function challengeView(){return `${header('Challenge This Purchase','Reconstruct the full case, test each claim and surface hidden relationships',`<button class="btn btn-outline" data-nav="case">Return to Case</button>`,`<button data-nav="case">Case Review</button> / Challenge`)}<div class="stack"><div class="challenge-hero"><div class="eyebrow" style="color:#93c5fd">PROCUREMENT STORY RECONSTRUCTION</div><h2>One purchase. Multiple pieces of evidence.</h2><p>ProcureMind compares what was requested, ordered, received, billed and approved, then searches nearby transactions for a pattern the single-case view could miss.</p><button class="btn" data-action="challenge" ${state.challenging?'disabled':''}>${state.challenged?'Run challenge again':'Challenge This Purchase'} ${icon('arrow')}</button></div><div class="card">${sectionHead('Review sequence',state.challenged?'Completed · 4 issues found':state.challenging?'Reviewing sample evidence now':'Ready to challenge this purchase')}<div class="card-body">${steps()}</div></div>${state.challenged?`<div class="card"><div class="result-head"><div><h2 class="section-title">4 issues found</h2><p class="section-sub">Each finding links back to a source record or policy clause.</p></div><span class="pill red">High risk · 89 / 100</span></div><div class="card-body issue-grid">${findings.map(findingCard).join('')}</div></div><div class="card">${sectionHead('The reconstructed story','Key turning points across the case')}<div class="card-body story-flow"><div class="story-node"><b>Request</b><span>10 units · USD 120k</span></div><span class="flow-arrow">→</span><div class="story-node"><b>PO issued</b><span>USD 120k</span></div><span class="flow-arrow">→</span><div class="story-node issue"><b>Partial receipt</b><span>8 of 10 units</span></div><span class="flow-arrow">→</span><div class="story-node issue"><b>Invoice</b><span>USD 135k · 10 units</span></div><span class="flow-arrow">→</span><div class="story-node issue"><b>Manager only</b><span>Director required</span></div></div></div><div class="product-banner"><div><div class="eyebrow" style="color:#9cc2ff">THE HIDDEN RELATIONSHIP</div><h2>PO-8794 adds USD 78,000 three days earlier.</h2><p>Same vendor, requester and category. Combined PO value is USD 198,000; invoice plus related PO exposure is USD 213,000. Human review is required to determine whether the purchases are linked.</p></div><div class="row wrap"><button class="btn" data-nav="related">Inspect relationship ${icon('arrow')}</button><button class="btn btn-outline" data-nav="secondlook">Challenge the finding</button></div></div><div class="card card-pad between wrap"><div><div class="eyebrow">RECOMMENDED DECISION</div><h2 style="font:800 21px Manrope;color:var(--red);margin:5px 0">HOLD PAYMENT</h2><div class="small muted">Do not release funds until price, delivery and approval evidence is resolved.</div></div><div class="row wrap"><button class="btn btn-outline" data-nav="policy">View policy</button><button class="btn btn-outline" data-nav="simulator">Open Repair Lab</button><button class="btn btn-primary" data-nav="actions">Open Action Center ${icon('arrow')}</button></div></div>`:''}</div>`}
function relatedView(){return `${header('Related Transactions','Inspect the relationship that a document-only review can miss',`<button class="btn btn-primary" data-nav="policy">Check applicable policy ${icon('arrow')}</button>`,`<button data-nav="case">Case Review</button> / Related Transactions`)}<div class="stack"><div class="grid-3">${metric('Current PO','USD 120,000','PO-8821 · May 5','file')}${metric('Related PO','USD 78,000','PO-8794 · May 2','related','amber')}${metric('Combined PO value','USD 198,000','USD 213,000 invoice + related PO exposure','risk','red')}</div><div class="card">${sectionHead('Relationship view','Two records connected by four shared attributes')}<div class="card-body"><div class="relation-view"><div class="relation-card current"><span class="pill blue">Current case</span><strong>PO-8821 · USD 120,000</strong><p>ABC Technology · May 5, 2026</p><button class="btn btn-plain" data-doc="PO">View source</button></div><div class="relation-line">4 shared signals</div><div class="relation-card related"><span class="pill amber">Related purchase</span><strong>PO-8794 · USD 78,000</strong><p>ABC Technology · May 2, 2026</p><button class="btn btn-plain" data-doc="REL">View source</button></div></div><div class="overlap-tags"><span>Same vendor</span><span>Same requester</span><span>Same category</span><span>3-day interval</span></div></div></div><div class="card">${sectionHead('Pattern assessment','Potential split purchase · investigation required')}<div class="card-body"><p style="font-size:13px;line-height:1.6;margin-top:0">The shared attributes and short interval justify cumulative review under Procurement Policy §4.5. The data does not prove intentional splitting. The current PO alone already exceeds the Director approval threshold under §4.2.</p><div class="policy-rule"><b>Review question:</b> Were PO-8794 and PO-8821 part of a single purchasing need? Confirm with the requester and review approval evidence for both transactions.</div></div></div><div class="card">${sectionHead('Related transaction record','Traceable source attributes')}<div class="table-wrap"><table class="table"><thead><tr><th>Transaction</th><th>Vendor</th><th>Requester</th><th>Department</th><th>Category</th><th>Date</th><th>Amount</th></tr></thead><tbody><tr><td>PO-8794</td><td>ABC Technology</td><td>Michael Tan</td><td>IT Infrastructure</td><td>End-user computing</td><td>May 2, 2026</td><td>USD 78,000</td></tr><tr><td>PO-8821</td><td>ABC Technology</td><td>Michael Tan</td><td>IT Infrastructure</td><td>End-user computing</td><td>May 5, 2026</td><td>USD 120,000</td></tr></tbody></table></div></div></div>`}
function policyView(){return `${header('Policy Compliance Review','Match the case evidence to the rule that governs the decision',`<button class="btn btn-primary" data-nav="risk">View risk decision ${icon('arrow')}</button>`,`<button data-nav="case">Case Review</button> / Policy Check`)}<div class="stack"><div class="grid-2"><div class="card">${sectionHead('Procurement Policy §4.2','Approval threshold')}<div class="card-body"><div class="policy-rule">Purchases above <b>USD 100,000</b> require <b>Director approval</b>. Emergency procurement may proceed with Head of Operations approval when the exception is documented.</div><div style="margin-top:13px">${[['Threshold exceeded','Yes · PO USD 120,000'],['Director approval present','No · Manager only'],['Emergency exception documented','No']].map(([a,b])=>`<div class="check-row"><span>${a}</span><b>${b}</b></div>`).join('')}</div><div class="between" style="margin-top:14px"><span class="pill red">Non-compliant</span><button class="source-link" data-doc="POL">View policy source</button></div></div></div><div class="card">${sectionHead('Procurement Policy §4.5','Cumulative transaction review')}<div class="card-body"><div class="policy-rule">Purchases with the <b>same vendor, requester and category within 7 days</b> must be reviewed cumulatively against the approval threshold.</div><div style="margin-top:13px">${[['Related PO found','PO-8794 · USD 78,000'],['Time between POs','3 days'],['Combined PO value','USD 198,000']].map(([a,b])=>`<div class="check-row"><span>${a}</span><b>${b}</b></div>`).join('')}</div><div class="between" style="margin-top:14px"><span class="pill amber">Review required</span><button class="source-link" data-doc="REL">View related PO</button></div></div></div></div><div class="card">${sectionHead('Policy determination','Evidence-backed, with explicit limits')}<div class="card-body"><div class="grid-2"><div class="surface card-pad"><span class="pill red">Confirmed gap</span><h3 style="font:800 14px Manrope">Director approval not found</h3><p class="small muted" style="line-height:1.5">APR-1138 records Manager approval only. The PO amount exceeds the §4.2 threshold.</p></div><div class="surface card-pad"><span class="pill amber">Needs investigation</span><h3 style="font:800 14px Manrope">Related purchases may be one activity</h3><p class="small muted" style="line-height:1.5">§4.5 requires cumulative review. Shared attributes are a signal, not a conclusion about intent.</p></div></div></div></div></div>`}
function riskView(){return `${header('Risk & Recommendation','Turn documented findings into a defensible payment decision',`<button class="btn btn-outline" data-nav="simulator">Open Repair Lab</button><button class="btn btn-primary" data-nav="actions">Open Action Center ${icon('arrow')}</button>`,`<button data-nav="case">Case Review</button> / Risk & Recommendation`)}<div class="stack"><div class="two-col"><div class="card">${sectionHead('Decision recommendation','Four independent findings support the decision')}<div class="card-body"><div class="between wrap"><div><span class="eyebrow">NEXT BEST DECISION</span><h2 style="font:800 29px Manrope;color:var(--red);margin:6px 0">HOLD PAYMENT</h2><p class="small muted" style="max-width:600px;line-height:1.6">Do not release payment until the USD 15,000 variance, two undelivered units and missing Director approval are resolved. Review the related PO before the final decision.</p></div><span class="pill red">High risk</span></div><div class="divider"></div>${['Invoice exceeds approved PO value by USD 15,000.','Receipt confirms 8 units while invoice bills 10.','Director approval required by §4.2 is absent.','Related PO warrants cumulative review under §4.5.'].map((t,i)=>`<div class="reason"><span class="reason-index">${i+1}</span>${t}</div>`).join('')}</div></div><div class="card">${sectionHead('Overall risk score','Illustrative rule-based prototype score')}<div class="card-body"><div class="score-ring"><div class="score-inner"><b>89</b><span>out of 100</span></div></div><div class="divider"></div><div class="small muted" style="line-height:1.55">Score shown for the sample case. This prototype does not use a live risk model or enterprise data.</div></div></div></div><div class="card">${sectionHead('Evidence supporting this recommendation','Open original sample records for each finding')}<div class="card-body issue-grid">${findings.map(findingCard).join('')}</div></div></div>`}
const clarification=`Subject: Clarification Required for Invoice INV-0092\n\nDear Procurement Team,\n\nBefore payment can proceed for case PC-2026-0187, please clarify the following and provide supporting records:\n\n1. Explain the USD 15,000 difference between PO-8821 (USD 120,000) and INV-0092 (USD 135,000), including any approved change order.\n2. Confirm delivery of the remaining two units or provide a corrected invoice for the eight units received under GR-6620.\n3. Provide the Director approval required by Procurement Policy §4.2.\n4. Confirm whether PO-8794 and PO-8821 were part of one purchasing need so cumulative review under §4.5 can be completed.\n\nPayment remains on hold pending review.\n\nRegards,\nProcurement Review Team`;
const approvalDraft=`Subject: Director Approval Required — PC-2026-0187\n\nPlease review PO-8821 for ABC Technology (USD 120,000). The recorded approval is Manager level, while Procurement Policy §4.2 requires Director approval above USD 100,000.\n\nThe case also contains an invoice variance, partial delivery and a related PO requiring cumulative review. Approval should follow resolution of these findings and should be recorded against the case.`;
function actionsView(){return `${header('Action Center','Move from findings to a controlled next step',`<span class="pill ${state.paymentHeld?'red':'amber'}">${status()}</span>`,`<button data-nav="case">Case Review</button> / Action Center`)}<div class="stack"><div class="product-banner"><div><div class="eyebrow" style="color:#9cc2ff">NEXT BEST ACTION</div><h2>Hold payment pending evidence resolution.</h2><p>The recommendation is supported by the invoice, receipt, approval record and policy clauses. All prototype actions remain local to this demo.</p></div><button class="btn" data-nav="audit">View audit trail ${icon('arrow')}</button></div><div class="grid-2"><div class="action-card"><span class="pill red">1 · Priority</span><h3>Hold Payment</h3><p>Record the hold decision against this case before further payment processing.</p><button class="btn btn-danger" data-action="hold" ${state.paymentHeld?'disabled':''}>${state.paymentHeld?'Payment Held':'Hold Payment'}</button></div><div class="action-card"><span class="pill amber">2 · Evidence</span><h3>Request Clarification</h3><p>Ask about the price variance, outstanding delivery and relationship between the two POs.</p><button class="btn btn-outline" data-action="clarification">Generate Clarification Draft</button></div><div class="action-card"><span class="pill amber">3 · Escalation</span><h3>Escalate for Review</h3><p>Flag the potential cumulative-purchase pattern for procurement and finance review.</p><button class="btn btn-outline" data-action="escalate" ${state.escalated?'disabled':''}>${state.escalated?'Escalated':'Escalate'}</button></div><div class="action-card"><span class="pill blue">4 · Approval</span><h3>Request Approval</h3><p>Prepare a Director approval request under Procurement Policy §4.2.</p><button class="btn btn-outline" data-action="approval">Request Approval</button></div></div>${state.draftType?`<div class="card" id="draft-panel">${sectionHead(state.draftType==='clarification'?'Generated Clarification Draft':'Director Approval Request','Editable draft for review; no message is sent from this prototype')}<div class="card-body"><div class="draft" id="draft-text">${state.draftType==='clarification'?clarification:approvalDraft}</div><div class="row wrap" style="margin-top:15px"><button class="btn btn-primary" data-action="copy-draft">Copy Draft</button><button class="btn btn-outline" data-action="log-draft">${state.draftType==='clarification'?'Record Clarification Request':'Record Approval Request'}</button><button class="btn btn-outline" data-action="edit-draft">Edit Draft</button></div></div></div>`:''}<div class="card">${sectionHead('Action checklist','Resolve each item before a final payment decision')}<div class="card-body">${[['Payment hold recorded',state.paymentHeld],['Invoice variance explained',false],['Remaining two units confirmed',false],['Director approval recorded',false],['Related purchase reviewed',false]].map(([x,done])=>`<div class="check-row"><span>${x}</span><span class="pill ${done?'green':'gray'}">${done?'Done':'Open'}</span></div>`).join('')}</div></div></div>`}
function controlsView(){return `${header('Controls & Rules','Turn a case finding into a reusable prevention control',`<button class="btn btn-primary" data-action="generate-control">Generate New Control ${icon('arrow')}</button>`)}<div class="stack"><div class="card">${sectionHead('Active controls','Illustrative control library')}<div class="table-wrap"><table class="table"><thead><tr><th>Control</th><th>Logic</th><th>Status</th><th>Last triggered</th></tr></thead><tbody><tr><td><strong>Price variance</strong></td><td>Invoice value exceeds approved PO</td><td><span class="pill green">Active</span></td><td>PC-2026-0187</td></tr><tr><td><strong>Delivery mismatch</strong></td><td>Billed quantity exceeds received quantity</td><td><span class="pill green">Active</span></td><td>PC-2026-0187</td></tr><tr><td><strong>Missing approval</strong></td><td>Approval role below policy threshold</td><td><span class="pill green">Active</span></td><td>PC-2026-0187</td></tr><tr><td><strong>Related transaction signal</strong></td><td>Same vendor and requester in short interval</td><td><span class="pill green">Active</span></td><td>PC-2026-0187</td></tr>${state.controlActive?'<tr><td><strong>Cumulative threshold review</strong></td><td>Same vendor, requester and category · 7 days · PO total &gt; USD 100,000</td><td><span class="pill green">Demo active</span></td><td>PC-2026-0187</td></tr>':''}</tbody></table></div></div><div class="card">${sectionHead('Control generation from discovered risk','Candidate rule based on the related-purchase finding')}<div class="card-body">${!state.controlDraft?`<div class="grid-2"><div><div class="eyebrow">GAP TO CLOSE</div><h3 style="font:800 18px Manrope">Cumulative threshold review</h3><p class="small muted" style="line-height:1.6">The case surfaced a nearby purchase with matching attributes. Generate a reusable rule to flag cumulative exposure before payment.</p></div><div class="surface card-pad"><b style="font-size:12px">Trigger in this case</b><p class="small muted">PO-8794 + PO-8821 = USD 198,000 over three days</p><button class="btn btn-primary" data-action="generate-control">Generate Control</button></div></div>`:`<div class="grid-2"><div><span class="pill blue">${state.controlActive?'Demo active':'Draft control'}</span><h3 style="font:800 18px Manrope">Cumulative threshold review</h3><p class="small muted" style="line-height:1.6">Flag POs from the same vendor, requester and category created within 7 days when their combined PO value exceeds USD 100,000.</p><div class="policy-rule"><b>Trigger:</b> same vendor + requester + category · within 7 days · cumulative PO total &gt; USD 100,000<br><b>Outcome:</b> require human review and Director approval check before payment.</div></div><div class="surface card-pad"><div class="eyebrow">TEST AGAINST HERO CASE</div><h3 style="font:800 16px Manrope">Would flag PC-2026-0187</h3><p class="small muted">Matched PO-8794 and PO-8821. Combined PO value: USD 198,000. Policy reference: §4.5.</p><button class="btn btn-primary" data-action="activate-control" ${state.controlActive?'disabled':''}>${state.controlActive?'Added to demo controls':'Add to Demo Controls'}</button><p class="small muted">Prototype change only; no enterprise rule engine is connected.</p></div></div>`}</div></div></div>`}
function reportsView(){return `${header('Reports','Case and portfolio summaries for management review',`<button class="btn btn-primary" data-action="export">${icon('download')} Export Case Summary</button>`)}<div class="stack"><div class="grid-3">${metric('Reviewed today','128','Illustrative portfolio view','cases')}${metric('High-risk share','11%','14 of 128 cases','risk','red')}${metric('Held for review','USD 1.24M','Illustrative portfolio view','actions','amber')}</div><div class="card">${sectionHead('Case spotlight','PC-2026-0187 · ABC Technology')}<div class="card-body"><div class="grid-4"><div><div class="metric-label">Invoice value</div><b>USD 135,000</b></div><div><div class="metric-label">Risk score</div><b style="color:var(--red)">89 / 100</b></div><div><div class="metric-label">Issues found</div><b>4</b></div><div><div class="metric-label">Decision</div><b>${state.paymentHeld?'Payment Held':'Hold Recommended'}</b></div></div><div class="divider"></div><p class="small muted">The export includes findings, source references, policy clauses and the local demo audit log.</p></div></div><div class="card">${sectionHead('Risk themes','Illustrative sample distribution')}<div class="card-body risk-bars"><div class="risk-bar"><span>Price variance</span><div class="bar-track"><div class="bar-fill red" style="width:76%"></div></div><b>19</b></div><div class="risk-bar"><span>Approval gap</span><div class="bar-track"><div class="bar-fill amber" style="width:60%"></div></div><b>15</b></div><div class="risk-bar"><span>Partial delivery</span><div class="bar-track"><div class="bar-fill amber" style="width:36%"></div></div><b>9</b></div><div class="risk-bar"><span>Related purchases</span><div class="bar-track"><div class="bar-fill red" style="width:24%"></div></div><b>6</b></div></div></div></div>`}
function auditView(){const all=[...state.audit,...baseAudit.slice().reverse()];return `${header('Audit Trail','Who did what, when, and against which evidence',`<button class="btn btn-outline" data-action="export">${icon('download')} Export Evidence Pack</button>`,`<button data-nav="case">Case Review</button> / Audit Trail`)}<div class="stack"><div class="card card-pad between wrap"><div><span class="eyebrow">CASE PC-2026-0187</span><h2 class="section-title" style="margin-top:6px">Review history</h2><p class="section-sub">Static source events plus actions taken during this local demo session.</p></div><span class="pill blue">${all.length} recorded events</span></div><div class="card">${sectionHead('Events','Most recent first')}<div class="card-body">${all.map(a=>`<div class="audit-item"><time>${a.time}</time><div><b>${a.what} <span class="muted" style="font-weight:500">· ${a.who}</span></b><p>${a.detail}</p></div></div>`).join('')}</div></div><div class="card">${sectionHead('Evidence index','Records supporting the case assessment')}<div class="card-body doc-grid">${['PO','GR','INV','APR','REL','POL'].map(documentCard).join('')}</div></div></div>`}
function settingsView(){return `${header('Demo Settings','Manage this illustrative prototype session')}<div class="card card-pad"><h2 class="section-title">Reset the walkthrough</h2><p class="page-sub" style="margin:8px 0 18px">Clear local challenge results and simulated actions to run the judge demo again.</p><button class="btn btn-outline" data-action="reset">Reset Demo</button></div>`}
function view(){switch(state.view){case'dashboard':return dashboard();case'cases':return casesView();case'queue':return queueView();case'case':return caseView();case'challenge':return challengeView();case'related':return relatedView();case'policy':return policyView();case'risk':return riskView();case'simulator':return simulatorView();case'secondlook':return secondLookView();case'actions':return actionsView();case'controls':return controlsView();case'reports':return reportsView();case'audit':return auditView();case'settings':return settingsView();default:return dashboard()}}
function render(){document.getElementById('app').innerHTML=state.signedIn?shell():loginView()}
function challenge(){if(state.challenging)return;state.view='challenge';state.challenged=false;state.challenging=true;state.stage=0;render();window.scrollTo({top:0,behavior:'smooth'});let i=0;clearInterval(timer);timer=setInterval(()=>{i++;state.stage=i;if(i>=stages.length){clearInterval(timer);state.challenging=false;state.challenged=true;addAudit('Purchase challenged','Four findings generated from PO-8821, GR-6620, INV-0092, APR-1138, PO-8794 and Procurement Policy §§4.2–4.5.','ProcureMind demo engine');}render()},420)}
function openDoc(k){const d=docs[k];if(!d)return;document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${d.title}"><div class="modal-head"><h2>${d.title}</h2><button class="x-btn" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body"><div class="between wrap"><span class="pill blue">${d.ref}</span><span class="small muted">${d.date}</span></div><p class="small muted">Source owner: ${d.owner}</p><div class="divider"></div>${d.facts.map(f=>`<div class="check-row"><span>${f.split(':')[0]}</span><b>${f.split(':').slice(1).join(':').trim()}</b></div>`).join('')}<p class="small muted" style="line-height:1.5;margin-top:18px">Illustrative source preview. Evidence labels and values are part of the demo dataset.</p></div></div></div>`}
function exportSummary(){const a=[`PROCUREMIND CASE REVIEW — PC-2026-0187`,`Vendor: ABC Technology`,`Requester: Michael Tan · IT Infrastructure`,`PO: USD 120,000 (PO-8821)`,`Invoice: USD 135,000 (INV-0092)`,`Goods received: 8 of 10 (GR-6620)`,`Approval: Manager found; Director required (APR-1138; Policy §4.2)`,`Related purchase: USD 78,000 (PO-8794)`,`Combined PO value: USD 198,000`,`Invoice plus related PO exposure: USD 213,000`,`Risk score: 89 / 100 · Recommended action: HOLD PAYMENT`,`Current demo status: ${status()}`,``,`FINDINGS`,...findings.map((f,i)=>`${i+1}. ${f.title.toUpperCase()} — ${f.copy} Evidence: ${f.evidence}`),``,`AUDIT EVENTS`,...[...state.audit,...baseAudit.slice().reverse()].map(x=>`${x.time} | ${x.who} | ${x.what} | ${x.detail}`),``,`Illustrative prototype data; no live enterprise connection.`].join('\n');const blob=new Blob([a],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='procuremind-PC-2026-0187-evidence-pack.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);addAudit('Evidence pack exported','Text summary downloaded for PC-2026-0187.');showToast('Evidence pack downloaded.');render()}
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();login()}});
document.addEventListener('input',e=>{if(e.target.id==='global-search'){state.search=e.target.value;state.view='cases';const pos=e.target.selectionStart;render();const el=document.getElementById('global-search');el.focus();el.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.id==='risk-filter'){state.riskFilter=e.target.value;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('modal-root').innerHTML='';});
document.addEventListener('click',async e=>{const t=e.target.closest('[data-nav],[data-doc],[data-action]');if(!t)return;if(t.dataset.nav){go(t.dataset.nav);return}if(t.dataset.doc){openDoc(t.dataset.doc);return}const action=t.dataset.action;if(action==='login'){login()}else if(action==='challenge'){challenge()}else if(action==='close-modal'){if(e.target===t||e.target.closest('.x-btn'))document.getElementById('modal-root').innerHTML=''}else if(action==='hold'){state.paymentHeld=true;addAudit('Payment hold recorded','Reviewer held payment for INV-0092 pending resolution of price, delivery and approval findings.');showToast('Payment hold recorded in the demo audit trail.');render()}else if(action==='clarification'){state.draftType='clarification';addAudit('Clarification draft generated','Draft references invoice variance, partial delivery, approval gap and related purchase.','ProcureMind demo engine');go('actions');setTimeout(()=>document.getElementById('draft-panel')?.scrollIntoView({behavior:'smooth',block:'start'}),40)}else if(action==='approval'){state.draftType='approval';addAudit('Approval request draft generated','Draft cites Procurement Policy §4.2 and open case findings.','ProcureMind demo engine');go('actions');setTimeout(()=>document.getElementById('draft-panel')?.scrollIntoView({behavior:'smooth',block:'start'}),40)}else if(action==='escalate'){state.escalated=true;addAudit('Case escalated','Reviewer escalated the related-purchase signal to procurement and finance review.');showToast('Escalation recorded in the demo audit trail.');render()}else if(action==='copy-draft'){const txt=document.getElementById('draft-text')?.innerText||'';try{await navigator.clipboard.writeText(txt);showToast('Draft copied to clipboard.')}catch{showToast('Copy unavailable in this browser; select the draft text instead.')}}else if(action==='log-draft'){if(state.draftType==='clarification'){state.clarificationRequested=true;addAudit('Clarification request recorded','Reviewer logged a request for price, delivery, approval and related-PO evidence. No message was sent.');showToast('Clarification request recorded locally.')}else{state.approvalRequested=true;addAudit('Director approval request recorded','Reviewer logged an approval request under Policy §4.2. No message was sent.');showToast('Approval request recorded locally.')}render()}else if(action==='edit-draft'){const box=document.getElementById('draft-text');box.contentEditable='true';box.focus();showToast('Draft is editable. Use Copy Draft to keep your changes.')}else if(action==='generate-control'){state.controlDraft=true;addAudit('Cumulative threshold control generated','Draft rule derived from PO-8794 + PO-8821 and Policy §4.5.','ProcureMind demo engine');showToast('Draft control generated from this case.');go('controls')}else if(action==='activate-control'){state.controlActive=true;addAudit('Demo control added','Cumulative threshold review added to the local demo control library.');showToast('Control added to the demo library.');render()}else if(action==='export'){exportSummary()}else if(action==='reset'){clearInterval(timer);state=fresh();login();showToast('Demo reset.')}});
render();






